solution.javascript:
function rotarDerecha(cabeza, k) {
  if (!cabeza || !cabeza.next) return cabeza;
  let n = 1, ultimo = cabeza;
  while (ultimo.next) { ultimo = ultimo.next; n++; }
  k %= n;
  if (k === 0) return cabeza;
  ultimo.next = cabeza; // anillo
  let nuevoFinal = ultimo;
  for (let i = 0; i < n - k; i++) nuevoFinal = nuevoFinal.next;
  const nuevaCabeza = nuevoFinal.next;
  nuevoFinal.next = null;
  return nuevaCabeza;
}
